test('S-003 · Audit every freeze and unfreeze event for the last 24 months meets latency budget', async ({ request }) => {
  const samples: number[] = [];
  for (let i = 0; i < 20; i++) {
    const t0 = Date.now();
    const res = await request.get('/audit_every_freeze_and_unfreeze_event_for_the_last_24_months');
    samples.push(Date.now() - t0);
    expect(res.ok()).toBeTruthy();
  }
  samples.sort((a, b) => a - b);
  const p95 = samples[Math.floor(samples.length * 0.95) - 1];
  expect(p95).toBeLessThan(2000);
});

